function clearSession1(){groupSession1=freshSession1();saveGroupSession1()}
function requestSession1Reset(){if(groupSession1.choices.length&&!confirm('Reset Session 1 and erase your current choices on this device?'))return false;clearSession1();return true}
function clampGroupScore(v){return Math.max(0,Math.min(100,v))}
function scoreDeltaText(v){return v>0?`+${v}`:String(v)}
function groupDecisionCode(){return groupSession1.choices.length?groupSession1.choices.join('-'):'—'}
function buildGroupScoreBoard(scores){return `<div class="group-score-board">${Object.entries(SESSION1_SCORE_LABELS).map(([key,label])=>`<div class="group-score-row"><div class="group-score-label">${label}</div><div class="group-score-bar" aria-hidden="true"><div class="group-score-fill" style="width:${scores[key]}%"></div></div><div class="group-score-value">${scores[key]}</div></div>`).join('')}</div>`}
function buildImpactPills(effect){return Object.entries(effect).map(([key,val])=>`<span class="group-impact-pill ${val>0?'positive':val<0?'negative':'neutral'}">${SESSION1_SCORE_LABELS[key]} ${scoreDeltaText(val)}</span>`).join('')}
function actualEffectForChoice(stepIndex,choiceId){const before=recomputeSession1Scores(groupSession1.choices.slice(0,stepIndex));const choices=groupSession1.choices.slice(0,stepIndex);choices.push(choiceId);const after=recomputeSession1Scores(choices);return Object.fromEntries(Object.keys(SESSION1_SCORE_LABELS).map(key=>[key,after[key]-before[key]]))}
function session1Option(stepIndex,choiceId){const step=SESSION1_STEPS[stepIndex];return step?step.options.find(o=>o.id===choiceId):null}
function session1SummaryCards(){return groupSession1.choices.map((choiceId,index)=>{const step=SESSION1_STEPS[index],opt=session1Option(index,choiceId);return opt?`<article class="group-summary-card"><span class="eyebrow">${esc(step.title)}</span><h4>${esc(opt.id+'. '+opt.title)}</h4><p>${esc(opt.text)}</p></article>`:''}).join('')}
function session1Profile(){const s=groupSession1.scores;if(s.access>=82&&s.equity>=82&&s.sustainability<58)return{title:'The ambitious access advocate',icon:'🌍',text:'Your plan strongly improves access and equity, but long-term financial or logistical stability remains fragile.'};if(s.innovation>=82&&s.access<60)return{title:'The innovation-first strategist',icon:'💼',text:'You protected innovation and industry confidence, but too many patients remain excluded from treatment.'};if(s.sustainability>=72&&s.access>=70&&s.equity>=70&&s.innovation>=65)return{title:'The balanced system builder',icon:'🏗️',text:'Your agreement balances access, fairness, innovation and feasibility unusually well.'};if(s.equity>=82&&s.equity>=Math.max(s.access,s.innovation,s.sustainability))return{title:'The equity champion',icon:'⚖️',text:'You consistently prioritised populations with the greatest need and reduced unfair inequalities.'};if(s.access>=82&&s.access>=Math.max(s.equity,s.innovation,s.sustainability))return{title:'The emergency responder',icon:'🚑',text:'You focused strongly on expanding access, especially in high-need settings.'};if(s.sustainability>=76&&s.sustainability>=Math.max(s.access,s.equity,s.innovation))return{title:'The long-term planner',icon:'♻️',text:'Your plan emphasises delivery capacity and the ability to keep the agreement working over time.'};if(s.innovation>=76&&s.innovation>=Math.max(s.access,s.equity,s.sustainability))return{title:'The market balancer',icon:'🔬',text:'Your decisions strongly protect the conditions needed for research and continued industry participation.'};return{title:'The pragmatic committee',icon:'🧠',text:'Your committee accepted trade-offs and built a defensible, if imperfect, global agreement.'}}
