function showGroupLibrary(focusCard=true){const library=$('#groupSessionLibrary'),detail=$('#session1Detail');if(library)library.hidden=false;if(detail)detail.hidden=true;if(focusCard)requestAnimationFrame(()=>$('#session1CardButton')?.focus())}
function openSession1Detail(){const library=$('#groupSessionLibrary'),detail=$('#session1Detail');if(library)library.hidden=true;if(detail)detail.hidden=false;renderSession1Welcome(false);requestAnimationFrame(()=>$('#session1DetailTitle')?.focus())}
function renderSession1Welcome(scroll=true){normaliseGroupSession1();const resume=groupSession1.choices.length&&!groupSession1.completed;const completed=groupSession1.completed;$('#groupMissionWorkspace').innerHTML=`<article><div class="group-sim-intro"><div class="group-sim-card"><span class="eyebrow">Session 1 mission</span><h3>Design a global access agreement for Novirex.</h3><p>You will make six decisions about allocation, pricing, licensing, royalties, manufacturing and emergency response.</p><ul class="group-steps"><li><strong>Option order is fixed.</strong> A–E means the same thing on every device.</li><li><strong>Discuss before confirming.</strong> Choose one shared answer as a team.</li><li><strong>There is no perfect score.</strong> Stronger performance in one area may reduce another.</li><li><strong>Keep your final decision code.</strong> It lets groups compare strategies exactly.</li></ul><div class="session-launch-actions">${completed?'<button class="primary-action" id="viewSession1Result">View previous result →</button><button id="startSession1Btn">↻ Start a new simulation</button>':`<button class="primary-action" id="startSession1Btn">${resume?'▶ Resume simulation':'▶ Start simulation'}</button>`}${groupSession1.choices.length&&!completed?'<button id="resetSession1Btn">Reset current choices</button>':''}</div></div><div class="group-sim-card"><span class="eyebrow">Game scores</span><h4>All four scores start at 50.</h4><p><strong>Access</strong> — can enough people obtain the medicine?<br><strong>Equity</strong> — are populations with the greatest need protected?<br><strong>Innovation</strong> — are incentives for research and cooperation preserved?<br><strong>Sustainability</strong> — can the agreement work over time?</p><div class="group-decision-code">Decision code: ${esc(groupDecisionCode())} · Ruleset ${SESSION1_RULESET}</div>${buildGroupScoreBoard(groupSession1.scores)}</div></div></article>`;const viewResult=$('#viewSession1Result');if(viewResult)viewResult.onclick=renderSession1Result;$('#startSession1Btn').onclick=()=>{if(completed)clearSession1();startSession1Flow()};const reset=$('#resetSession1Btn');if(reset)reset.onclick=()=>{if(requestSession1Reset())renderSession1Welcome()};if(scroll)$('#groupMissionWorkspace').scrollIntoView({behavior:scrollBehavior(),block:'start'})}
function startSession1Flow(){normaliseGroupSession1();groupSession1.completed=false;if(groupSession1.step>=SESSION1_STEPS.length)clearSession1();saveGroupSession1();renderSession1Step()}
function renderSession1Step(){normaliseGroupSession1();if(groupSession1.completed||groupSession1.step>=SESSION1_STEPS.length){renderSession1Result();return}if(groupSession1.outcome){renderSession1Outcome();return}const step=SESSION1_STEPS[groupSession1.step];const progress=Math.round((groupSession1.step/SESSION1_STEPS.length)*100);$('#groupMissionWorkspace').innerHTML=`<article><div class="group-sim-progress"><div><strong>Decision ${groupSession1.step+1} of ${SESSION1_STEPS.length}</strong><span>${esc(step.title.replace(/^Step \d+ · /,''))}</span></div><div class="group-sim-progress-track" aria-hidden="true"><div style="width:${progress}%"></div></div></div><div class="group-step-meta"><span class="eyebrow">${esc(step.title)}</span><div class="group-decision-code">Decision code: ${esc(groupDecisionCode())}</div></div><h3 id="session1StepHeading" tabindex="-1">${esc(step.question)}</h3><p>${esc(step.note)}</p>${buildGroupScoreBoard(groupSession1.scores)}<div class="group-choice-grid">${step.options.map(o=>`<button type="button" class="group-choice-card" data-group-choice="${o.id}" aria-pressed="false"><span class="choice-letter">${o.id}</span><strong>${esc(o.title)}</strong><p>${esc(o.text)}</p></button>`).join('')}</div><div class="group-step-actions"><button id="confirmGroupChoice" class="primary-action" disabled>Confirm this group choice</button><button id="backToSession1Overview">Session overview</button></div><div id="groupChoiceHint" class="fiction-note" role="status" aria-live="polite">Discuss all five options, then select one shared answer.</div></article>`;let selected=null;$$('[data-group-choice]').forEach(btn=>btn.onclick=()=>{selected=btn.dataset.groupChoice;$$('[data-group-choice]').forEach(x=>{const on=x===btn;x.classList.toggle('selected',on);x.setAttribute('aria-pressed',String(on))});$('#confirmGroupChoice').disabled=false;$('#groupChoiceHint').textContent=`Selected option ${selected}. Confirm only when the whole team agrees.`});$('#confirmGroupChoice').onclick=()=>selected&&applySession1Choice(selected);$('#backToSession1Overview').onclick=()=>renderSession1Welcome();requestAnimationFrame(()=>$('#session1StepHeading')?.focus());$('#groupMissionWorkspace').scrollIntoView({behavior:scrollBehavior(),block:'start'})}
function compatibilityNote(stepIndex,choiceId){if(stepIndex!==4)return'';const licence=groupSession1.choices[2];if(licence==='A'&&choiceId!=='A')return'Your manufacturing plan is broader than the single-country bilateral licence chosen in Step 3. Your committee would need to widen or renegotiate that licence.';if(licence==='C'&&choiceId==='D')return'An open manufacturing network is broader than the regional licences chosen in Step 3. Your committee would need to expand the legal coverage.';if(licence==='E'&&['D','E'].includes(choiceId))return'This production strategy goes beyond a short emergency licence. Your committee would need a broader or longer-term licensing agreement.';return''}
function applySession1Choice(choiceId){const step=SESSION1_STEPS[groupSession1.step],option=step?.options.find(o=>o.id===choiceId);if(!option)return;groupSession1.choices=groupSession1.choices.slice(0,groupSession1.step);groupSession1.choices[groupSession1.step]=choiceId;groupSession1.scores=recomputeSession1Scores(groupSession1.choices);groupSession1.outcome={stepIndex:groupSession1.step,choiceId,consistency:compatibilityNote(groupSession1.step,choiceId)};saveGroupSession1();renderSession1Outcome()}
function renderSession1Outcome(){const result=groupSession1.outcome;if(!result){renderSession1Step();return}const step=SESSION1_STEPS[result.stepIndex],option=session1Option(result.stepIndex,result.choiceId);if(!step||!option){groupSession1.outcome=null;saveGroupSession1();renderSession1Step();return}const actualEffect=actualEffectForChoice(result.stepIndex,result.choiceId);const progress=Math.round(((result.stepIndex+1)/SESSION1_STEPS.length)*100);$('#groupMissionWorkspace').innerHTML=`<article><div class="group-sim-progress"><div><strong>Decision ${result.stepIndex+1} of ${SESSION1_STEPS.length} complete</strong><span>Read the consequence before continuing.</span></div><div class="group-sim-progress-track" aria-hidden="true"><div style="width:${progress}%"></div></div></div><div class="group-step-meta"><span class="eyebrow">${esc(step.title)} · consequence</span><div class="group-decision-code">Decision code: ${esc(groupDecisionCode())}</div></div><h3 id="session1OutcomeHeading" tabindex="-1">You chose ${esc(option.id+'. '+option.title)}</h3>${buildGroupScoreBoard(groupSession1.scores)}<div class="group-consequence-box"><strong>What happens next?</strong><p>${esc(option.consequence)}</p>${result.consistency?`<p class="group-consistency-note"><strong>Agreement check:</strong> ${esc(result.consistency)}</p>`:''}<div class="group-impact-pills">${buildImpactPills(actualEffect)}</div><p class="group-score-cap-note"><small>Score changes above show the points actually applied after the 0–100 score limits.</small></p></div><div class="group-step-actions"><button id="continueSession1" class="primary-action">${result.stepIndex===SESSION1_STEPS.length-1?'See final result →':'Continue to the next decision →'}</button><button id="restartSession1Mid">Restart simulation</button></div></article>`;$('#continueSession1').onclick=()=>{groupSession1.step=result.stepIndex+1;groupSession1.outcome=null;if(groupSession1.step>=SESSION1_STEPS.length){groupSession1.completed=true;ensureSession1Completed()}saveGroupSession1();groupSession1.completed?renderSession1Result():renderSession1Step()};$('#restartSession1Mid').onclick=()=>{if(requestSession1Reset())renderSession1Welcome()};requestAnimationFrame(()=>$('#session1OutcomeHeading')?.focus());$('#groupMissionWorkspace').scrollIntoView({behavior:scrollBehavior(),block:'start'})}
function renderSession1Result(){normaliseGroupSession1();if(groupSession1.choices.length!==SESSION1_STEPS.length){groupSession1.completed=false;groupSession1.step=Math.min(groupSession1.choices.length,SESSION1_STEPS.length-1);saveGroupSession1();renderSession1Step();return}groupSession1.completed=true;saveGroupSession1();ensureSession1Completed();const profile=session1Profile();$('#groupMissionWorkspace').innerHTML=`<article><div class="group-profile-banner"><div class="group-profile-icon" aria-hidden="true">${profile.icon}</div><div><span class="eyebrow">Session 1 complete</span><h3 id="session1ResultHeading" tabindex="-1">${esc(profile.title)}</h3><p>${esc(profile.text)}</p></div></div><div class="group-result-box"><div class="group-step-meta"><strong>Final decision code</strong><div class="group-decision-code">${esc(groupDecisionCode())}</div></div>${buildGroupScoreBoard(groupSession1.scores)}</div><div class="group-summary-grid">${session1SummaryCards()}</div><div class="group-briefing-grid"><div class="group-sim-card"><span class="eyebrow">Final speaking task</span><h4>Your 90-second group briefing</h4><ol class="group-steps"><li>State your main priority.</li><li>Explain one difficult trade-off.</li><li>Refer to at least two decisions from your code.</li><li>Say what you would monitor next.</li><li><strong>Every team member must speak.</strong></li></ol><div class="group-vocab-badges">${SESSION1_VOCAB.map(v=>`<span class="badge">${esc(v)}</span>`).join('')}</div></div><div class="group-sim-card"><span class="eyebrow">Briefing support</span><h4>A possible structure</h4><p>“Our committee designed a global access agreement for Novirex. Our main priority was … We chose … because … The most difficult trade-off was … On balance, we recommend … We would monitor … to assess the impact of the agreement.”</p><p><small>Your decision code uniquely identifies this sequence of choices. The same code always gives the same scores when both devices show Ruleset ${SESSION1_RULESET}.</small></p></div></div><div class="group-step-actions"><button id="restartSession1Final" class="primary-action">↻ Play again</button><button id="returnSession1Overview">Session overview</button><button id="returnGroupLibrary">← Back to sessions</button></div></article>`;$('#restartSession1Final').onclick=()=>{clearSession1();renderSession1Step()};$('#returnSession1Overview').onclick=()=>renderSession1Welcome();$('#returnGroupLibrary').onclick=()=>showGroupLibrary();requestAnimationFrame(()=>$('#session1ResultHeading')?.focus());$('#groupMissionWorkspace').scrollIntoView({behavior:scrollBehavior(),block:'start'})}
function assignGroupRoles(){const size=+$('#groupSize').value||4;const assigned=size===3?['Access Lead','Equity Lead','Supply Lead + Innovation Lead']:SESSION1_ROLES;$('#groupRoleDraw').hidden=false;$('#groupRoleDraw').innerHTML=`<h3>Team roles · ${size} students</h3><div class="role-pills">${assigned.map((r,i)=>`<span class="role-pill">Student ${i+1}: ${esc(r)}</span>`).join('')}</div><p class="fiction-note">Role assignment is fixed for consistency. You may swap roles as a team before starting.</p>`}
window.openPublicHealthSession1=openSession1Detail;
function initSession1GroupActivity(){normaliseGroupSession1();$('#session1CardButton')?.addEventListener('click',openSession1Detail);$('#backToGroupSessions')?.addEventListener('click',()=>showGroupLibrary());$('#startSession1Hero')?.addEventListener('click',()=>{renderSession1Welcome();});$('#assignGroupRoles')?.addEventListener('click',assignGroupRoles);$('#groupSize')?.addEventListener('change',()=>{const roleBox=$('#groupRoleDraw');if(roleBox&&!roleBox.hidden)assignGroupRoles()});showGroupLibrary(false);updateAll()}
initSession1GroupActivity();
